from datetime import datetime
from pathlib import Path

import pytest
import geopandas as gpd
import pandas as pd
from shapely import wkt

from satchip import download_data, models

DATA_PATH = Path(__file__).parent / "data"


def pytest_addoption(parser):
    parser.addoption("--download", action="store_true", default=False)


def pytest_configure(config):
    config.addinivalue_line("markers", "download: marks tests that download data")


def pytest_collection_modifyitems(config, items):
    if not config.getoption("--download"):
        skip = pytest.mark.skip(reason="pass --download to run")
        for item in items:
            if item.get_closest_marker("download"):
                item.add_marker(skip)


@pytest.fixture
def pristine_gdf(tmp_path):
    shp_path = DATA_PATH / "hwds_pristine"
    df = gpd.read_file(shp_path)

    df["SwathDate"] = pd.to_datetime(df["SwathDate"], format="%Y-%m-%d")
    df["HLSDate"] = pd.to_datetime(df["HLSDate"], format="%Y-%m-%d")

    return df


@pytest.fixture(scope="session")
def s2_local_files(s2_event):
    download_path = DATA_PATH / "raw"
    print('Downloading test data...')

    local_files = download_data.download_data(s2_event, models.HLS_S30, download_path)

    return local_files


